use vstd::prelude::*;

verus! {

fn swap_first_and_last(a: &Vec<i32>) -> (result: Vec<i32>)
    requires
        a.len() > 0,
    ensures
        result.len() == a.len(),
        // If length is 1, the vector is unchanged
        a.len() == 1 ==> result@ == a@,
        // If length is at least 2, first/last are swapped and middle stays the same
        a.len() >= 2 ==> result[0] == a[a.len() - 1],
        a.len() >= 2 ==> result[a.len() - 1] == a[0],
        a.len() >= 2 ==> (forall|i: int|
            0 < i && i < (a.len() as int) - 1 ==> result[i as usize] == a[i as usize]
        ),
{
    let n = a.len();
    debug_assert!(n > 0);

    if n == 1 {
        return a.clone();
    }

    let mut result = a.clone();
    result[0] = a[n - 1];
    result[n - 1] = a[0];
    result
}

} // verus!

